-- ds_resolution — GENERATED by tools/build_production.py from tools/dashboard_datasets.py.
-- Paste into the dashboard's Data tab as a dataset named ds_resolution.
-- One row per problem with the flags the resolution counters average. Triage: Closure rate, MTTR, Disposition coverage, Recurrence, Advice followed, Decision-record gaps.

WITH gaps AS (
  SELECT cohort_id, COUNT(*) AS integrity_gaps
  FROM   sdpt_data_trnf.udp_brnz.dq_results_v_disposition_integrity
  GROUP  BY cohort_id
)
SELECT v.cohort_id, v.raised_ts, v.severity, v.business_domain,
       CASE WHEN v.lifecycle_state LIKE 'closed%' THEN 1 ELSE 0 END             AS is_closed,
       v.mttr_days,
       CASE WHEN v.lifecycle_state <> 'awaiting_triage'
             AND v.latest_decision IS NOT NULL THEN 1 ELSE 0 END                AS has_decision,
       CASE WHEN c.is_recurrence THEN 1 ELSE 0 END                              AS is_recurrence,
       CASE WHEN v.recommendation_followed THEN 1
            WHEN v.recommendation_followed = FALSE THEN 0 END                   AS advice_followed,
       COALESCE(g.integrity_gaps, 0)                                            AS integrity_gaps
FROM   sdpt_data_trnf.udp_brnz.dq_results_v_cohort_current v
JOIN   sdpt_data_trnf.udp_brnz.dq_results_v_cohort_for_bi c ON c.cohort_id = v.cohort_id
LEFT JOIN gaps g ON g.cohort_id = v.cohort_id
